// One PeerMux server (one UDP port) hosting peers,
// cross-connected to ordinary single-socket clients: both
// pairs connect concurrently and echo on the same channel
// label without cross-talk.

import assert from "node:assert/strict";
import test from "node:test";
import { Peer } from "../peer.js";
import { PeerMux } from "../mux.js";

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function waitFor(fn, timeoutMs = 15000) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    const value = fn();
    if (value) return value;
    await sleep(20);
  }
  return null;
}

test("two pairs share one server socket", { timeout: 90000 }, async (t) => {
  const mux = await PeerMux.bind({ address: "127.0.0.1", port: 0 });
  t.after(() => mux.close());
  const muxPort = mux.address().port;

  const pairs = [];
  for (let pair = 0; pair < 2; pair++) {
    const answerer = await mux.createPeer({ localIps: ["127.0.0.1"] });
    const offerer = await Peer.create({ localIps: ["127.0.0.1"] });
    t.after(async () => {
      await offerer.close();
      await answerer.close();
    });
    // The mux peer advertises the shared port.
    const sdp = answerer.createOffer();
    assert.ok(
      sdp.includes(`:${muxPort} `) || sdp.includes(` ${muxPort} typ`),
      "answerer candidates must use the mux port",
    );
    pairs.push({ pair, offerer, answerer });
  }

  const runPair = async ({ pair, offerer, answerer }) => {
    const offer = offerer.createOffer();
    const answer = answerer.handleOffer(offer);
    offerer.handleAnswer(answer);
    const [offererEp, answererEp] = await Promise.all([offerer.connect(), answerer.connect()]);

    let heard = null;
    answererEp.onchannel = (ch) => {
      ch.onmessage = (event) => {
        heard = Buffer.isBuffer(event.data) ? event.data.toString() : String(event.data);
        ch.send(Buffer.from(`re:${heard}`));
      };
    };
    const channel = offererEp.openChannel({ label: "echo" });
    let reply = null;
    channel.onmessage = (event) => {
      reply = Buffer.isBuffer(event.data) ? event.data.toString() : String(event.data);
    };
    channel.send(Buffer.from(`hello-from-pair-${pair}`));
    assert.equal(await waitFor(() => heard), `hello-from-pair-${pair}`);
    assert.equal(await waitFor(() => reply), `re:hello-from-pair-${pair}`);
  };

  await Promise.all(pairs.map(runPair));
});
